    foot = f'<footer><div class="wrap"><span>© {SITE}</span><a href="{up}about.html">من نحن</a><a href="{up}contact.html">اتصل بنا</a><a href="{up}privacy.html">سياسة الخصوصية</a></div></footer>'
    inner = f'{nav}<main class="wrap">{body}</main>{foot}'
    full = f'<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<title>{e(title)}</title>\n<meta name="description" content="{e(desc)}">\n<link rel="canonical" href="{BASE}{clean(path)}">\n{ADS}\n{FONTS}\n<style>{CSS}</style>\n</head>\n<body>\n{inner}\n</body>\n</html>\n'
