    if "حساس" in m: return ("حساس صغير يقيس الحرارة أو الضغط في نقطة من المكيف يعطي قراءة غير منطقية، أو سلكه مفصول.", POWER+" هذا كل ما يُعمل من جهتك.", "إن عاد الرمز. الفني يقيس الحساس بجهاز القياس ويستبدله إن كان تالفاً، وهو من أبسط الإصلاحات.")
