    if "الصمام الرباعي" in m: return ("الصمام الذي يحوّل المكيف بين التبريد والتدفئة لا يبدّل الاتجاه.", "جرّب التحويل بين التبريد والتدفئة مرة واحدة بعد إعادة التشغيل.", "إن بقي الرمز. الصمام أو ملفه يحتاج فحصاً.")
    return ("خلل رصده المكيف وأوقف التشغيل بسببه.", POWER, "إن عاد الرمز بعد إعادة التشغيل.")
