        if "دخول الماء" in m or "تعبئة" in m or "مستوى الماء" in m or "لم يصل" in m or "ماء غير كافٍ" in m or "ضغط أو حرارة الماء" in m: return ("الماء لا يدخل الجهاز، أو يدخل أبطأ من المطلوب.", "تأكد أن المحبس مفتوح كاملاً وأن خرطوم الدخول غير مثني. أغلق المحبس وفكّ الخرطوم ونظّف المصفاة الصغيرة عند طرفه.", "إن كان الماء يصل بضغط جيد وبقي الرمز. صمام الدخول أو حساس المستوى يحتاج فحصاً.")
        if "كهرباء" in m or "جهد" in m or "تيار" in m or "تردد" in m: return ("الكهرباء الواصلة للجهاز انقطعت أو ليست بالقيمة المطلوبة.", "وصّل الجهاز بمقبس جداري مباشرة دون وصلة تمديد، وأعد القاطع إن كان قد نزل، ثم أعد تشغيل الدورة.", "إن تكرر الرمز. يُقاس الجهد عند المقبس، وهذا عمل كهربائي.")
        if "حساس" in m or "حرار" in m or "تسخين" in m or "سخان" in m or "سخونة" in m or "يسخن" in m or "ساخن" in m: return ("الجهاز يقرأ حرارة غير متوقعة، أو الماء أو الهواء لا يسخن كما يجب.", RST + " ثم شغّل دورة والجهاز فارغ لترى هل يعود الرمز.", "إن عاد الرمز. السخان أو حساس الحرارة يُقاس بجهاز القياس ويُستبدل إن كان تالفاً.")
        if "زر" in m: return ("لوحة التحكم تقرأ زراً كأنه مضغوط باستمرار.", "اضغط كل زر مرة وتأكد أنه يرتدّ، وامسح اللوحة من أي بلل أو دهون.", "إن بقي الرمز واللوحة جافة ونظيفة.")
        if "محرك" in m or "المحرك" in m: return ("المحرك لا يدور كما يُطلب منه.", "خفّف الحمولة، ثم " + RST, "إن عاد الرمز بحمولة خفيفة.")
        if "مروحة" in m or "مضخة" in m or "المضخة" in m or "عاكس" in m or "وظيفة" in m or "قابض" in m: return ("قطعة متحركة داخل الجهاز لا تعمل كما يجب، أو شيء يعيق حركتها.", "تأكد أن لا شيء يعيق الأجزاء المتحركة داخل الحوض، ثم " + RST, "إن عاد الرمز. القطعة نفسها تحتاج فحصاً.")
