    if "مروحة" in m or "المروحة" in m: return ("مروحة التبريد لا تدور كما يجب.", "أطفئ الانفرتر وانظر هل شيء يسد فتحة المروحة، ونظّف الغبار من الخارج.", "إن بقي الرمز. المروحة تُستبدل.")
    if "حمل زائد" in m or _re.search(r"تيار.*زائد", m) or "قصر" in m: return ("التيار المار في الانفرتر أعلى مما يتحمله.", "افصل الأحمال الكبيرة ثم أعد التشغيل، وشغّلها بعد ذلك واحداً واحداً لتعرف أيها السبب.", "إن ظهر دون أحمال كبيرة. قد يكون في التمديدات قصر أو في الانفرتر خلل.")
    if "تواصل" in m or "VE.Bus" in m or "CAN" in m or "الأجهزة" in m or "جهاز" in m or "الطور" in m or "طور" in m or "العدّاد" in m or "إرسال" in m or "المتوازي" in m: return ("وحدات النظام لا تتبادل البيانات كما يجب: انفرتر مع آخر، أو مع العدّاد أو وحدة المراقبة.", "تأكد أن كيابل التواصل مثبتة في منافذها وأن كل الوحدات تعمل، ثم " + RST, "إن بقي الرمز. إعدادات الربط بين الوحدات يراجعها المركِّب.")
    if "الإعداد" in m or "إعداد" in m or "مضبوط" in m: return ("إعداد في الانفرتر لا يناسب النظام الموصول به.", "لا تغيّر الإعدادات بالتجربة.", "في كل الحالات. المركِّب يراجع الإعداد المقصود.")
