def guide_vfd(r):
    m, c, who = r[4], r[5] or "", r[6]
    RST = "أوقف المحرك، وافصل التغذية عن الانفرتر وانتظر حتى تنطفئ شاشته ولمبة الشحن، ثم أعد التشغيل."
    if who == N: return ("حالة تشغيل وليست عطلاً.", "لا شيء يحتاج إصلاحاً.", "إن منعت الحالة التشغيل دون سبب واضح.")
    if "زمن التشغيل" in m or "مؤقت الصيانة" in m: return ("الانفرتر بلغ عدد ساعات التشغيل المضبوط للتنبيه. تذكير صيانة وليس عطلاً.", "نفّذ الصيانة الدورية ثم صفّر المؤقت كما يشرح الكتيّب.", "إن لم يُصفَّر المؤقت.")
    if "أُعيدت" in m: return ("إعدادات الانفرتر عادت إلى ضبط المصنع.", "أعد إدخال بيانات لوحة المحرك وإعدادات التشغيل قبل تشغيله.", "إن عادت الإعدادات إلى ضبط المصنع وحدها أكثر من مرة.")
