    if "قفل" in m or "مقفل" in m or "كلمة مرور" in m: return ("لوحة التشغيل أو الإعدادات مقفلة عمداً.", "افتح القفل بالطريقة المذكورة في كتيّب الانفرتر أو بكلمة المرور.", "إن كانت كلمة المرور مفقودة.")
    if "كتابة مُدخل" in m or "ضبط مُدخل" in m or "ضبط المصنع" in m: return ("محاولة تغيير إعداد لا يُسمح بتغييره الآن، أو قيمة خارج المدى.", "أوقف المحرك قبل تعديل الإعدادات، وراجع المدى المسموح للمُدخل في الكتيّب.", "إن تكرر مع قيم صحيحة.")
    if "تسريب أرضي" in m or "الأرضي" in m: return ("تيار يتسرب من أحد أطوار الخرج إلى الأرض، وغالباً من كيبل المحرك أو ملفاته.", "افصل التغذية ولا تُعد التشغيل مراراً.", "في كل الحالات. يُقاس عزل كيبل المحرك وملفاته بجهاز الميجر بعد فصلهما عن الانفرتر.")
    if "تيار زائد" in m or "قصر" in m or "تيار الخرج" in m: return ("التيار ارتفع فجأة فوق حد الانفرتر: حمل ثقيل، تسارع أسرع من اللازم، أو قصر في المحرك أو كيبله.", "تأكد أن الحمل الميكانيكي غير محشور ويدور باليد، ثم " + RST, "إن عاد الرمز. يُزاد زمن التسارع أو التباطؤ، ويُفحص عزل المحرك وكيبله.")
    if "جهد زائد" in m: return ("جهد الخط المستمر داخل الانفرتر ارتفع فوق الحد. يحدث غالباً عند إيقاف حمل ذي قصور كبير بسرعة، أو مع جهد تغذية مرتفع.", RST, "إن تكرر. يُزاد زمن التباطؤ أو تُركَّب مقاومة كبح، ويُقاس جهد التغذية.")
    if "فقدان طور في الخرج" in m or "الخرج" in m: return ("أحد الأطوار الثلاثة بين الانفرتر والمحرك مقطوع أو غير متوازن.", "افصل التغذية ولا تشغّل المحرك على طورين.", "في كل الحالات. تُفحص أطراف كيبل المحرك عند الانفرتر وعند المحرك، والكونتاكتور إن وُجد بينهما.")
    if ("جهد" in m and "منخفض" in m) or "فقدان طور في الدخل" in m or "التغذية" in m or "الأطوار" in m or "الشحن" in m or "الفيوز" in m: return ("التغذية الواصلة للانفرتر ناقصة: جهد منخفض، طور مفقود، أو هبوط لحظي.", "تأكد أن القاطع والفيوزات قبل الانفرتر سليمة وأن الأطوار الثلاثة موجودة.", "إن كانت التغذية سليمة وبقي الرمز. تُفحص دائرة الشحن والمكثفات داخل الانفرتر.")
    if "حمل زائد" in m or "تعثر" in m or "التعثر" in m or "فترة طويلة" in m or "الحمل" in m: return ("المحرك أو الانفرتر يعمل فوق تياره المقنّن مدة أطول من المسموح.", "خفّف الحمل، وتأكد أن الآلة غير محشورة وأن تهوية المحرك غير مسدودة.", "إن تكرر بحمل عادي. تُراجع قيمة تيار المحرك المُدخلة في الإعدادات ومقاس الانفرتر.")
    if "سخونة" in m or "حرار" in m or "ثرمستور" in m or "المروحة" in m or "مروحة" in m or "برودة" in m: return ("حرارة الانفرتر أو المحرك خارج الحد المسموح.", "نظّف فلاتر اللوحة الكهربائية ومشتت الانفرتر من الغبار، وتأكد أن مروحته تدور وأن حرارة الغرفة مقبولة.", "إن بقي الرمز والتهوية جيدة. المروحة أو حساس الحرارة يُستبدل.")
    if "تواصل" in m or "RS-485" in m or "Ethernet" in m or "IP" in m or "شبكة" in m or "لوحة المفاتيح" in m or "لوحة التشغيل" in m or "USB" in m: return ("الانفرتر فقد الاتصال بلوحة تشغيله أو بوحدة التحكم التي ترسل له الأوامر.", "تأكد أن كيبل التواصل ولوحة المفاتيح مثبتان في مكانيهما.", "إن بقي الرمز. تُراجع إعدادات التواصل والعنوان والسرعة، ويُفحص الكيبل من التشويش.")
    if "الضبط التلقائي" in m: return ("الانفرتر لم يستطع قياس خصائص المحرك أثناء الضبط التلقائي.", "تأكد أن المحرك موصول وغير محمّل، وأن بيانات لوحته مُدخلة صحيحة، ثم أعد الضبط.", "إن فشل مرة أخرى.")
    if "PID" in m or "تناظري" in m or "التناظري" in m or "دخل التيار" in m or "الجفاف" in m or "المضخة" in m or "الفلتر" in m or "الانحشار" in m or "مرات التشغيل" in m: return ("إشارة الحساس الخارجي الذي ينظّم به الانفرتر العملية مفقودة أو خارج المدى، أو تفعّلت حماية خاصة بالمضخة.", "افحص الحساس وسلكه، وتأكد أن الماء يصل المضخة وأن لا شيء يسدها.", "إن كان الحساس والمضخة سليمين وبقي الرمز.")
    if "إنكودر" in m or "الإنكودر" in m or "سرعة" in m or "السرعة" in m or "التزامن" in m or "موضع" in m or "تسارع" in m: return ("السرعة الفعلية للمحرك تخالف ما يطلبه الانفرتر، أو إشارة حساس الدوران مفقودة.", "تأكد أن الحمل غير محشور، ثم " + RST, "إن عاد الرمز. يُفحص الإنكودر وكيبله وإعدادات التحكم.")
