def guide_cash(r):
    m, c, who = r[4], r[5] or "", r[6]
    CL = "نظّف الحساسات بفرشاة ناعمة أو ورقة التنظيف كما يشرح كتيّب الآلة."
    if who == N: return ("حالة تشغيل وليست عطلاً. الآلة تفعل ما ضُبطت عليه.", "لا شيء يحتاج إصلاحاً.", "إن ظهرت دون أن تكون ضبطتها على ذلك.")
    if "لا معلومات" in m or "تعذّر التعرف" in m or "نسبة التعرف على الورقة" in m or "تخالف المقروءة" in m: return ("الآلة لم تحصل على قراءة كافية أو متطابقة لهذه الورقة، فلم تحسم فئتها.", "أعد عدّ الورقة وحدها. " + CL, "إن تكرر مع أوراق سليمة بعد التنظيف. الحساس يحتاج معايرة.")
    if "مثنية" in m: return ("زاوية الورقة مثنية فرفضتها الآلة.", "افرد الزاوية وأعد عدّ الورقة.", "إن رفضت الآلة أوراقاً مفرودة.")
    if "ممتلئ" in m: return ("الجيب الذي تتجمع فيه الأوراق امتلأ فتوقف العدّ.", "أفرغ الجيب ثم تابع.", "إن ظهر والجيب فارغ. حساس الجيب متسخ أو معطل.")
    if "مائل" in m or "تدخل مائلة" in m: return ("الورقة دخلت مائلة فلم تستطع الآلة قراءتها.", "رتّب الرزمة واطرقها على الطاولة لتستوي حوافها، ووسّطها بين موجّهَي الدرج.", "إن تكرر مع رزم مرتبة. بكرات التغذية تحتاج تنظيفاً أو استبدالاً.")
    if "ورقتان" in m or "المسافة" in m or "سماكة" in m: return ("ورقتان دخلتا معاً أو متلاصقتين.", "افصل الأوراق الملتصقة وهوِّ الرزمة قبل وضعها، واضبط برغي فجوة التغذية إن كان في آلتك.", "إن تكرر مع أوراق جافة ومفصولة. بكرات التغذية متآكلة.")
    if "تسلسلي" in m or "القائمة السوداء" in m: return ("الآلة لم تستطع قراءة الرقم التسلسلي، أو وجدته يخالف ما ضُبطت عليه.", "افحص الورقة يدوياً وأعد عدّها.", "إن فشلت القراءة مع أوراق سليمة كثيرة. الحساس يحتاج تنظيفاً أو معايرة.")
    if "باركود" in m: return ("الآلة لم تجد الباركود على التذكرة أو لم تستطع قراءته.", "اقلب التذكرة وأعد إدخالها.", "إن تكرر مع تذاكر واضحة الطباعة.")
    if "فئة" in m or "عملة" in m or "وجه" in m or "اتجاه" in m or "إصدار" in m or "الإصدار" in m: return ("ورقة تخالف بقية الرزمة في الفئة أو العملة أو الاتجاه أو الإصدار، فرفضتها الآلة بحسب وضع العدّ المختار.", "أخرج الورقة المختلفة، أو غيّر وضع العدّ إن كان الخلط مقصوداً.", "إن رفضت الآلة أوراقاً مطابقة. تحتاج تحديث برنامج العملات.")
    if "UV" in m or "MG" in m or "المغناطيسية" in m or "اللون" in m or "ثنية" in m or "مثنية" in m: return ("خاصية أمان في الورقة لا تطابق ما تتوقعه الآلة. قد تكون الورقة مشتبهاً بها، أو متسخة، أو الحساس متسخاً.", "اعزل الورقة وافحصها يدوياً. " + CL, "إن رفضت الآلة أوراقاً سليمة كثيرة بعد التنظيف. الحساس يحتاج معايرة.")
    if "مقاس" in m or "طول" in m or "عرض" in m or "ارتفاع" in m or "حاف" in m or "الحافة" in m or "حافتي" in m: return ("مقاس الورقة كما قرأته الآلة لا يطابق الفئة: ورقة ممزقة أو مطوية، أو فئة أخرى.", "افحص الورقة وافردها، ووسّط الرزمة بموجّهَي الدرج.", "إن تكرر مع أوراق سليمة.")
    if "حساس" in m or "معلومات" in m or "التعرف" in m: return ("الآلة لم تحصل على قراءة كافية لهذه الورقة.", "أعد عدّ الورقة. " + CL, "إن تكرر بعد التنظيف.")
    return ("خلل رصدته الآلة عند التشغيل أو أثناء العدّ.", "أزل الأوراق وأي جسم غريب من الدرج ومسار الورق، ثم أطفئ الآلة وشغّلها.", "إن عاد الرمز.")
def guide_printer(r):
    m, c, who = r[4], r[5] or "", r[6]
    if who == N: return ("حالة تشغيل وليست عطلاً.", "لا شيء يحتاج إصلاحاً.", "إن بقيت الحالة ومنعت الطباعة.")
    if "متوقفة مؤقتاً" in m: return ("الطابعة في وضع الإيقاف المؤقت.", "اضغط زر التغذية مرة لتستأنف الطباعة.", "إن دخلت الإيقاف المؤقت وحدها مراراً.")
    if "الفحص الذاتي" in m: return ("الطابعة لم تجتز فحصها عند التشغيل، أو أن رأسها يبرد بعد سخونة.", "انتظر دقيقتين. إن بقيت اللمبة فأطفئ الطابعة دقيقة ثم شغّلها.", "إن بقي النمط بعد إعادة التشغيل.")
